//go:build arm64 && gc && !purego

package argon2

import "golang.org/x/sys/cpu"

// useSHA3 selects the kernels that fold each XOR-and-rotate into one XAR
// instruction (Armv8.2 SHA-3: every Apple core, Neoverse V1 and later). Every
// arm64 CPU Go supports has Advanced SIMD, so the NEON kernels need no probe.
var useSHA3 = cpu.ARM64.HasSHA3

// The kernels are generated by tools/genblamka. They compute
// out = in1 ^ in2 ^ P(in1 ^ in2), or out ^= that for the XOR forms, where P
// is the BLAMKA permutation, on a 1 KiB scratch area in their own frame.
// out may be in1 or in2.

//go:noescape
func processBlockNEON(out, in1, in2 *block)

//go:noescape
func processBlockXORNEON(out, in1, in2 *block)

//go:noescape
func processBlockSHA3(out, in1, in2 *block)

//go:noescape
func processBlockXORSHA3(out, in1, in2 *block)

func processBlock(out, in1, in2 *block) {
	if useSHA3 {
		processBlockSHA3(out, in1, in2)
		return
	}
	processBlockNEON(out, in1, in2)
}

func processBlockXOR(out, in1, in2 *block) {
	if useSHA3 {
		processBlockXORSHA3(out, in1, in2)
		return
	}
	processBlockXORNEON(out, in1, in2)
}
